<template><EnterpriseAuthShell><div class="auth-panel"><div class="identification"><span class="id-icon">企</span><div><strong>企业工作区</strong><small>由企业子域名识别入口</small></div></div><span class="eyebrow">企业登录</span><h2>登录到您的工作区</h2><p class="subtitle">管理员与员工使用同一企业账户入口，继续访问已获授权的 Sub2API 服务。</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="mb-5"/><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><el-form-item label="企业邮箱" prop="email"><el-input v-model="form.email" type="email" size="large" autocomplete="username" :prefix-icon="Message" /></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" size="large" show-password autocomplete="current-password" :prefix-icon="Lock" @keyup.enter="submit" /></el-form-item><el-button type="primary" size="large" :loading="loading" @click="submit">登录</el-button></el-form><div class="auth-links"><RouterLink to="/enterprise/forgot-password">忘记密码</RouterLink></div></div></EnterpriseAuthShell></template>
<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRoute, useRouter, RouterLink } from 'vue-router'; import type { FormInstance, FormRules } from 'element-plus'; import { Lock, Message } from '@element-plus/icons-vue'; import EnterpriseAuthShell from '@/components/enterprise/EnterpriseAuthShell.vue'; import { useEnterpriseAuthStore } from '@/stores/enterpriseAuth'; import { enterpriseHome } from '@/router/enterpriseGuard'
const auth = useEnterpriseAuthStore(), route = useRoute(), router = useRouter(); const formRef = ref<FormInstance>(); const loading = ref(false), error = ref(''); const form = reactive({ email: '', password: '' }); const rules: FormRules = { email: [{ required: true, type: 'email', message: '请输入有效邮箱', trigger: 'blur' }], password: [{ required: true, message: '请输入密码', trigger: 'blur' }] }
async function submit() { if (!await formRef.value?.validate().catch(() => false)) return; loading.value = true; error.value = ''; try { const principal = await auth.login(form); const redirect = typeof route.query.redirect === 'string' && route.query.redirect.startsWith('/enterprise/') ? route.query.redirect : enterpriseHome(principal.role); await router.replace(principal.force_password_change ? '/enterprise/change-password' : redirect) } catch (e) { error.value = (e as { message?: string }).message || '登录失败' } finally { loading.value = false } }
</script>
<style scoped>.mb-5{margin-bottom:20px}.auth-links span{color:#94a3b8;text-align:right}.identification{display:flex;align-items:center;gap:10px;margin-bottom:18px}.identification .id-icon{display:grid;width:32px;height:32px;place-items:center;border-radius:7px;background:#eff6ff;color:#2563eb;font-weight:700}.identification strong{display:block;font-size:14px}.identification small{display:block;margin-top:2px;color:#94a3b8;font-size:12px}.eyebrow{display:block;margin-bottom:6px;color:#2563eb;font-size:12px;font-weight:700}</style>
